# brute force optimizer comparison
def brute(queries,pids,sig):
    pairs=[]
    for i in range(len(pids)):
        for j in range(i+1,len(pids)): pairs.append((pids[i],pids[j]))
    univ=0; cov={}
    for q in queries:
        mask=0
        for k,(a,b) in enumerate(pairs):
            if sig[(q['id'],a)]!=sig[(q['id'],b)]: mask|=1<<k
        cov[q['id']]=mask; univ|=mask
    if univ==0: return ([],0,0)
    best=None
    qs=[q['id'] for q in queries]
    cost={q['id']:q['cost'] for q in queries}
    for r in range(len(qs)+1):
        for combo in itertools.combinations(qs,r):
            u=0
            for c in combo: u|=cov[c]
            if u==univ:
                cst=sum(cost[c] for c in combo)
                key=(cst,len(combo))
                if best is None or key<best[0]:
                    best=(key,combo)
    return (sorted(best[1]),best[0][0],best[0][1])

